    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidate(principal, resource, request, out var validationDecision))
            return validationDecision;

        var context = CreateAuthorizationContext(principal!, resource!, request!, delegations);

        if (TryEvaluateExceptionalAccess(principal!, resource!, request!, context, out var exceptionalDecision))
            return exceptionalDecision;

        if (TryEvaluateAction(request!, context, out var actionDecision))
            return actionDecision;

        return CreateSuccessfulDecision(resource!, request!, context.Delegated);
    }

    private static bool TryValidate(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (TryValidateContext(principal, resource, request, out decision))
            return true;
        if (TryValidateIdentityAndStatus(principal!, resource!, out decision))
            return true;

        return TryValidateRequestConstraints(principal!, resource!, request!, out decision);
    }

    private static bool TryValidateContext(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateIdentityAndStatus(
        Principal principal,
        Resource resource,
        out AccessDecision decision)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }
        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateRequestConstraints(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }
        if (request.MinuteOfDay is < 0 or > 1439)
